def transform(grid):
    out = []
    for br in range(0, len(grid), 5):
        row = []
        for bc in range(0, len(grid[0]), 5):
            count = sum(grid[r][c] != 0 and grid[r][c] != grid[0][0] for r in range(br, min(br+4, len(grid))) for c in range(bc, min(bc+4, len(grid[0]))))
            row.append(1 if count == 2 else grid[0][0])
        out.append(row)
    return out
